-- TORVO V2 PUBLIC REPAIR REQUEST INTAKE
-- CUSTOMER CONTACT IS STORED PRIVATELY; PUBLIC CALL RETURNS ONLY REQUEST ID/STATUS.
create or replace function public_create_repair_request(p_full_name text,p_mobile text,p_pin_code text,p_brand text,p_model_number text,p_problem_description text,p_marketing_opt_in boolean default false)
returns table(requirement_id uuid,status text)
language plpgsql security definer set search_path=public as $$declare v_mobile text;v_customer uuid;v_id uuid;begin
 if nullif(btrim(p_full_name),'') is null then raise exception 'NAME REQUIRED';end if;v_mobile:=regexp_replace(coalesce(p_mobile,''),'\D','','g');if length(v_mobile)>10 then v_mobile:=right(v_mobile,10);end if;if length(v_mobile)<>10 then raise exception 'VALID 10 DIGIT MOBILE REQUIRED';end if;if btrim(coalesce(p_pin_code,''))!~'^[0-9]{6}$' then raise exception 'VALID 6 DIGIT PIN CODE REQUIRED';end if;if length(btrim(coalesce(p_problem_description,'')))<5 then raise exception 'PROBLEM DESCRIPTION REQUIRED';end if;
 insert into customer_contacts(full_name,mobile,whatsapp,pin_code,marketing_opt_in,marketing_opt_in_at,marketing_opt_in_source) values(upper(btrim(p_full_name)),v_mobile,v_mobile,btrim(p_pin_code),coalesce(p_marketing_opt_in,false),case when p_marketing_opt_in then now() end,case when p_marketing_opt_in then 'repair_request' end) on conflict(mobile) do update set full_name=excluded.full_name,whatsapp=excluded.whatsapp,pin_code=excluded.pin_code,marketing_opt_in=case when customer_contacts.marketing_opt_out_at is not null then false else customer_contacts.marketing_opt_in or excluded.marketing_opt_in end,marketing_opt_in_at=case when customer_contacts.marketing_opt_out_at is null and excluded.marketing_opt_in then coalesce(customer_contacts.marketing_opt_in_at,now()) else customer_contacts.marketing_opt_in_at end,updated_at=now() returning id into v_customer;
 insert into customer_service_requirements(customer_id,brand,model_number,problem_description,customer_pin_code,status) values(v_customer,nullif(upper(btrim(p_brand)),''),nullif(upper(btrim(p_model_number)),''),upper(btrim(p_problem_description)),btrim(p_pin_code),'received') returning id into v_id;
 return query select v_id,'RECEIVED'::text;end$$;
revoke all on function public_create_repair_request(text,text,text,text,text,text,boolean) from public;grant execute on function public_create_repair_request(text,text,text,text,text,text,boolean) to anon,authenticated;
